  const parts=await import('@nautilus-engine/core/parts'),fixtures=await import('@nautilus-engine/core/parts/fixtures'),interactions=await import('@nautilus-engine/core/interactions'),contracts=await import('@nautilus-engine/core/contracts'),packageFS=await import('node:fs');
